if getattr(mibBuilder, 'version', (0, 0, 0)) > (4, 4, 0):
    if mibBuilder.loadTexts: ciscoVtpMIB.setRevisionsDescriptions(('Added following OBJECT-GROUP\n        - vtpSourceInterfaceGroup\n        - vtpConfigFileGroup\n        - vtpVlanLocalShutdownGroup\n        - vtpLocalUpdaterGroup\n        - vtpDeviceIdGroup\n        Added new compliance\n        - vtpMIBCompliance16.', 'Added vlanTrunkPortActiveVlansGroup.\n        Updated the description of vtpServerDisabled.', 'Added vtpTrunkPruningGroup3 and\n        vtpConfigNotificationsGroup8. Modified the\n        description of vtpNotificationsEnabled and\n        managementDomainPruningState.', 'Added vlanStatsGroup. Deprecated\n        vtpConfigNotificationsGroup5 and replaced\n        it with vtpConfigNotificationsGroup6 and\n        vtpConfigNotificationsGroup7.', 'Correct the descriptions of the object\n        vtpConfigDigestErrors and the tables vtpVlanTable\n        and vtpInternalVlanTable.', 'Removed the OwnerString TEXTUAL-CONVENTION and\n        imported the same from RMON-MIB.', "Added 'dynamicGvrp(4)' for the TC VlanTypeExt.", "Add vtpInternalVlanGrp to configure internal\n        VLANs' allocation policy and show the owner \n        application names.", 'Split vtpConfigNotificationsGroup into two groups:\n        vtpConfigNotificationsGroupRev1 and \n        vtpConfigNotificationsGroup5. Write a new compliance\n        statement to list vtpConfigNotificationsGroupRev1 in\n        instead of vtpConfigNotificationsGroup in the \n        MANDATORY-GROUPS.', 'Modify the description of the TC VlanIndex.', "Add support for VTP version 3 features.\n        -- Add enumerators and modify the 'DESCRIPTION' of 6 \n           existing objects: \n           vtpVersion, managementDomainLocalMode,\n           managementDomainConfigRevNumber, \n           managementDomainLastUpdater,\n           managementDomainLastChange,  \n           managementDomainVersionInUse.\n        -- Add 3 new groups: vtpAuthGroup, \n           vtpDiscoverGroup, vtpDatabaseGroup.", '-- Add 4 new notifications/traps vtpLocalModeChanged,\n        vtpVersionInUseChanged, vtpVlanCreated and \n        vtpVlanDeleted. \n        -- Add 2 new objects vtpVlanCreatedNotifEnabled and \n        vtpVlanDeletedNotifEnabled to control the\n        generation of vtpVlanCreated and vtpVlanDeleted.\n        -- Use vtpNotificationsEnabled to control the\n        generation of vtpLocalModeChanged and\n        vtpVersionInUseChanged by grouping them in a\n        new group vtpConfigNotificationsGroup2.  \n        -- Deprecate the object vlanTrunkPortsDot1qTag and\n        its related group.', 'Deprecate the object, vlanTrunkPortDot1qTunnel.', 'Add a new off(4) mode to managementDomainLocalMode.', 'Deprecate read-only object vtpVlanEditTypeExt and\n        add a new read-create object vtpVlanEditTypeExt2.\n        Enable Notification groups.', 'Added Remote SPAN (RSPAN) VLAN feature, VLAN\n        management features without supporting VTP protocol\n        and a new object to handle one-VLAN-editing.', 'Added the mapping from VLAN ID to its corresponding\n        ifIndex', 'Added 4k VLAN editing and Dot1qTunnel support', 'Added 4k VLAN support', 'Added import of NOTIFICATION-GROUP', 'Added support for encapsulation type notApplicable', 'Added support for encapsulation type negotiation', 'Added Backup CRF object', 'Added ARE and STE hop counts.', 'Added support for turning on VTP for Trunk cards.', 'Added support for version 2 features.', 'Updated the Token-Ring support.', 'Updated to include objects in support of VTP pruning.', 'Initial version of this MIB module.',))
