vlanTrunkPortVlansXmitJoined = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 46, 1, 6, 1, 1, 11), OctetString().subtype(subtypeSpec=ValueSizeConstraint(128, 128)).setFixedLength(128)).setMaxAccess("readonly")
